def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    demand = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        total += o
        group = (props.get(site.get('element')) or {}).get('group')
        if group is None:
            continue
        if 15 <= group <= 17:
            demand += o * (18.0 - group)
        elif group == 1 or group == 2:
            demand -= o * group
        elif group == 13:
            demand -= 3.0 * o
    return demand / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    coordination = [0.0 for t in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.25 * (a + b):
                coordination[i] += occ[j]
    mean = sum(occ[i] * coordination[i] for i in range(n)) / total
    variance = sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n)) / total
    return sqrt(max(0.0, variance))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    groups = [(props.get(t.get('element')) or {}).get('group') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    eligible = [groups[i] is not None and 15 <= groups[i] <= 17 and radii[i] is not None and radii[i] > 0 for i in range(n)]
    total = sum(occ[i] for i in range(n) if eligible[i])
    if total <= 0:
        return 0.0
    coordination = [0.0 for t in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and eligible[i] and d is not None and 0 < d <= 6:
            b = radii[j]
            if b is not None and b > 0 and d <= 1.25 * (radii[i] + b):
                coordination[i] += occ[j]
    return sum(occ[i] for i in range(n) if eligible[i] and coordination[i] <= 0) / total

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    occupied = 0.0
    sphere_volume = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        occupied += o
        radius = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if radius is not None and radius > 0:
            sphere_volume += o * (4.0 * pi / 3.0) * radius ** 3
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        vpa = s.get('volume_per_atom_A3')
        volume = vpa * occupied if vpa is not None and vpa > 0 else 0.0
    return sphere_volume / volume if volume > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    valid = [r is not None and r > 0 for r in radii]
    total = sum(occ[i] for i in range(n) if valid[i])
    if total <= 0:
        return 0.0
    nearest = [3.0 for t in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if valid[i] and valid[j] and occ[j] > 0:
                ratio = d / (radii[i] + radii[j])
                if ratio < nearest[i]:
                    nearest[i] = ratio
    return sum(occ[i] * nearest[i] for i in range(n) if valid[i]) / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [t.get('element') for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    occupied = sum(occ)
    if occupied <= 0:
        return 0.0
    amounts = {}
    for i in range(n):
        element = elements[i]
        amounts[element] = amounts.get(element, 0.0) + occ[i]
    expected = 1.0 - sum((v / occupied) ** 2 for v in amounts.values())
    contacts = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.25 * (a + b):
                w = occ[i] * occ[j]
                contacts += w
                if elements[i] != elements[j]:
                    unlike += w
    return unlike / contacts - expected if contacts > 0 else 0.0
